package ru.nikita.lab2.service.impl;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import ru.nikita.lab2.api.dto.AccountDto;
import ru.nikita.lab2.api.dto.OperationDto;
import ru.nikita.lab2.api.enumeration.OpType;
import ru.nikita.lab2.dao.entity.AccountEntity;
import ru.nikita.lab2.dao.entity.OperationEntity;
import ru.nikita.lab2.dao.repository.AccountRepository;
import ru.nikita.lab2.dao.repository.OperationRepository;
import ru.nikita.lab2.dao.repository.UserRepository;
import ru.nikita.lab2.domain.Operation;
import ru.nikita.lab2.domain.User;
import ru.nikita.lab2.service.OperationService;
import ru.nikita.lab2.service.exception.InsufficientFundsException;
import ru.nikita.lab2.service.exception.InvalidAmountException;
import ru.nikita.lab2.service.exception.NoAccountFoundException;

import java.util.List;
import java.util.UUID;

@Service
public class OperationServiceImpl implements OperationService {

    private final AccountRepository accountRepository;
    private final OperationRepository operationRepository;
    private final UserRepository userRepository;


    public OperationServiceImpl(AccountRepository accountRepository, OperationRepository operationRepository,
                                UserRepository userRepository) {
        this.accountRepository = accountRepository;
        this.operationRepository = operationRepository;
        this.userRepository = userRepository;
    }

    @Override
    @Transactional
    public void deposit(UUID accountId, double amount) {
        validateAmount(amount);
        AccountEntity account = findAccount(accountId);

        account.setBalance(
                account.getBalance() + amount
        );

        accountRepository.save(account);
        OperationEntity operation = new OperationEntity(
                account,
                OpType.DEPOSIT,
                amount,
                0
        );
        operationRepository.save(operation);
    }

    @Override
    @Transactional
    public void withdraw(UUID accountId, double amount) {
        validateAmount(amount);
        AccountEntity account = findAccount(accountId);

        if (account.getBalance() < amount) {
            throw new InsufficientFundsException();
        }

        account.setBalance(
                account.getBalance() - amount
        );
        accountRepository.save(account);

        OperationEntity operation = new OperationEntity(
                account,
                OpType.WITHDRAW,
                amount,
                0
        );

        operationRepository.save(operation);
    }


    @Override
    @Transactional
    public void transfer(UUID fromAccountId, UUID toAccountId, double amount) {
        validateAmount(amount);

        if(fromAccountId.equals(toAccountId)){
            throw new IllegalArgumentException("Cannot transfer to the same account");
        }
        AccountEntity fromAccount =
                findAccount(fromAccountId);

        AccountEntity toAccount =
                findAccount(toAccountId);

        UUID senderId = fromAccount.getUser().getId();
        UUID recieverId = toAccount.getUser().getId();

        double commissionRate;

        if (senderId.equals(recieverId)){
            commissionRate = 0.0;
        } else if (userRepository.countFriendship(senderId, recieverId) > 0) {
            commissionRate = 0.03;
        }
        else {
            commissionRate = 0.10;
        }
        double commission = amount * commissionRate;
        double totalWithdraw = amount + commission;

        if(fromAccount.getBalance() < totalWithdraw){
            throw new InsufficientFundsException();
        }

        fromAccount.setBalance(fromAccount.getBalance() - totalWithdraw);
        toAccount.setBalance(toAccount.getBalance() + amount);
        accountRepository.save(fromAccount);
        accountRepository.save(toAccount);

        OperationEntity withdrawOperation = new OperationEntity(
                fromAccount,
                OpType.TRANSFER,
                -totalWithdraw,
                commission
        );

        OperationEntity depositOperation = new OperationEntity(
                toAccount,
                OpType.TRANSFER,
                amount,
                0
        );

        operationRepository.save(withdrawOperation);
        operationRepository.save(depositOperation);

    }

    @Override
    @Transactional(readOnly = true)
    public List<Operation> getOperation(
            OpType type,
            UUID accountId
    ){
        return operationRepository
                .findFiltered(type, accountId)
                .stream()
                .map(this::toDomain)
                .toList();
    }

    private AccountEntity findAccount(UUID accountId){
        return accountRepository.findById(accountId)
                .orElseThrow(NoAccountFoundException::new);
    }

    private void validateAmount(double amount){
        if (amount <= 0){
            throw new InvalidAmountException();
        }
    }

    private Operation toDomain(OperationEntity entity){
        return new Operation(
                entity.getId(),
                entity.getAccount().getId(),
                entity.getOpType(),
                entity.getAmount(),
                entity.getCommission(),
                entity.getOparationInstant()
        );
    }
}                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             